cd /tmp && cat > vt-shot.mjs <<'EOF'
import { chromium } from '/home/vercel-sandbox/.npm/_npx/e41f203b7505f1fb/node_modules/playwright-core/index.mjs'
const browser = await chromium.launch()
const page = await (await browser.newContext({ viewport: { width: 1000, height: 700 } })).newPage()
await page.addInitScript(`
  const orig = Document.prototype.startViewTransition;
  Document.prototype.startViewTransition = function (arg) {
    const vt = orig.call(this, arg);
    vt.ready.then(() => {
      // freeze every transition animation at 45% so we can screenshot mid-flight
      for (const a of document.getAnimations()) {
        if (!a.effect?.pseudoElement) continue;
        a.pause();
        const t = a.effect.getComputedTiming();
        a.currentTime = (t.delay ?? 0) + (t.duration ?? 0) * 0.45;
      }
      window.__frozen = true;
    });
    return vt;
  };
`)
await page.goto('http://localhost:3123/')
await page.waitForSelector('.product-card'); await page.waitForTimeout(1500)
await page.screenshot({ path: '/tmp/1-grid.png' })
await page.click('a[href="/product/wireless-headphones"]')
await page.waitForFunction(() => window.__frozen)
await page.screenshot({ path: '/tmp/2-mid-morph.png' })
await browser.close()
EOF
node vt-shot.mjs && ls -la /tmp/*.png
